import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { searchablePaths } from "./repo-metrics.mjs";

const root = fileURLToPath(new URL("..", import.meta.url));
const MAP_PATH = "docs/MAP.md";
const MAX_BYTES = 3072;
const SOURCE_FOLDER = /^(?:packages|apps)\/[^/]+\/src(?:\/|$)/;
const WORKSPACE_DEPTH = 2;

const HEADER = [
  "# Source map",
  "",
  "Generated by `npm run map -- --write` from the owner lines in `scripts/repo-map.mjs`, and held",
  "current by `repo-map.test.ts`. Rules and reasons live in [ARCHITECTURE.md](./ARCHITECTURE.md).",
  "",
];

export const OWNERS = {
  "apps/examples/src": "worked examples that tests read",
  "apps/pieces/src": "pieces agents and people make",
  "apps/pieces/src/live": "live editor",
  "apps/pieces/src/moves": "moves written for this app's pieces",
  "packages/rig/src": "joint vocabulary",
  "packages/rig/src/frame": "world frames",
  "packages/rig/src/ik/fabrik": "FABRIK",
  "packages/rig/src/ik/shared": "chains, goals, limits",
  "packages/rig/src/ik/solve2d": "2D solve",
  "packages/rig/src/ik/solve3d": "3D solve",
  "packages/dom/src": "DOM and SVG renderer",
  "packages/moves/src": "moves, time, pose",
  "packages/player/src": "scene player, manual driver",
  "packages/physics/src": "physics",
  "packages/rapier/src": "Rapier",
  "packages/react/src": "React hooks",
  "packages/three/src": "Three.js adapter",
  "packages/tools/src/scene/templates": "motion:new templates",
  "packages/tools/src/page": "page tools",
  "packages/tools/src/scene": "scene sample, timeline",
  "packages/tools/src/timeline": "timeline bars",
  "packages/tools/src/vite": "live editor Vite plugin",
};

function publicEntries(workspace, scanRoot = root) {
  const manifest = JSON.parse(readFileSync(join(scanRoot, workspace, "package.json"), "utf8"));
  return Object.keys(manifest.exports ?? {});
}

function workspaceOf(folder) {
  return folder.split("/").slice(0, WORKSPACE_DEPTH).join("/");
}

function lineFor(folder, owner) {
  const inside = folder.split("/").slice(WORKSPACE_DEPTH).join("/");
  return `- \`${inside}/\`: ${owner}`;
}

export function render(owners = OWNERS, entriesOf = publicEntries) {
  const folders = Object.keys(owners).sort();
  const lines = [...HEADER];
  for (const workspace of [...new Set(folders.map(workspaceOf))]) {
    const entries = entriesOf(workspace);
    lines.push(`## ${workspace}`, "");
    if (entries.length > 0)
      lines.push(`Public: ${entries.map((entry) => `\`${entry}\``).join(", ")}`, "");
    for (const folder of folders)
      if (workspaceOf(folder) === workspace) lines.push(lineFor(folder, owners[folder]));
    lines.push("");
  }
  return `${lines.join("\n").trimEnd()}\n`;
}

/** Folders holding source now; a tracked file already deleted from disk does not count. */
export function sourceFolders(scanRoot = root) {
  const folders = searchablePaths(scanRoot)
    .filter((path) => existsSync(join(scanRoot, path)))
    .map((path) => dirname(path).replaceAll("\\", "/"))
    .filter((folder) => SOURCE_FOLDER.test(`${folder}/`));
  return [...new Set(folders)];
}

export function mapProblems(folders, owners = OWNERS, entriesOf = () => []) {
  const known = new Set(folders);
  const problems = [
    ...folders
      .filter((folder) => owners[folder] === undefined)
      .map((folder) => `${folder}: source folder with no line in OWNERS`),
    ...Object.keys(owners)
      .filter((folder) => !known.has(folder))
      .map((folder) => `${folder}: OWNERS names a folder the tree does not hold`),
  ];
  if (problems.length > 0) return problems;
  if (Buffer.byteLength(render(owners, entriesOf)) > MAX_BYTES)
    return [`${MAP_PATH}: over ${MAX_BYTES} bytes, shorten the owner lines`];
  return [];
}

/** The one question this asks of the committed map: is it what the tree and the owners say now. */
export function checkMap(scanRoot = root) {
  const entriesOf = (workspace) => publicEntries(workspace, scanRoot);
  const problems = mapProblems(sourceFolders(scanRoot), OWNERS, entriesOf);
  if (problems.length > 0) return problems;
  const target = join(scanRoot, MAP_PATH);
  const committed = existsSync(target) ? readFileSync(target, "utf8") : "";
  return committed === render(OWNERS, entriesOf)
    ? []
    : [`${MAP_PATH} is out of date: run npm run map -- --write`];
}

export function main(argv = process.argv.slice(2), scanRoot = root) {
  if (argv.includes("--write")) {
    const entriesOf = (workspace) => publicEntries(workspace, scanRoot);
    writeFileSync(join(scanRoot, MAP_PATH), render(OWNERS, entriesOf), "utf8");
  }
  const problems = checkMap(scanRoot);
  if (problems.length > 0) {
    console.error(problems.join("\n"));
    return 1;
  }
  console.log(`${MAP_PATH} current: ${Object.keys(OWNERS).length} folders`);
  return 0;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) process.exitCode = main();
